(function(){
'use strict';
const api=window.VersionCompassSOAR,d=window.VersionCompassSOARData,parsed=api.read(location.search);let state=parsed.state,linkErrors=parsed.errors,model;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const themed=u=>window.VersionCompassTheme?.href(u)||u;
const labels={cmp:'Customer-managed (CMP)',cloud:'SOAR Cloud',commercial:'Commercial','fr-m':'FedRAMP Moderate','fr-h':'FedRAMP High',unspecified:'Not specified',unprivileged:'Unprivileged',privileged:'Privileged / conversion needed',supported:'Supported OS — exact version to verify',rhel7:'RHEL 7',centos7:'CentOS 7',al2:'Amazon Linux 2',aws:'AWS',gcp:'Google Cloud',azure:'Microsoft Azure'};
const fields={deployment:'SOAR deployment',from:'Current release',to:'Target release',installation:'Installation',os:'Current OS',compliance:'Environment',provider:'Provider',region:'Region'};
const values=k=>api.selectable(k,state);
const options=k=>values(k).map(v=>'<option value="'+esc(v)+'">'+esc(labels[v]||v)+'</option>').join('');
const field=k=>'<label data-soar-field="'+k+'" for="soar-'+k+'"><span>'+fields[k]+'</span><select id="soar-'+k+'" aria-label="'+fields[k]+'" data-soar="'+k+'">'+options(k)+'</select></label>';
document.documentElement.classList.add('perspective-enabled');document.body.classList.add('soar-view');
for(const href of ['perspectives.css','soar.css']){const css=document.createElement('link');css.rel='stylesheet';css.href=href;document.head.appendChild(css);}
new ResizeObserver(()=>document.documentElement.style.setProperty('--perspective-header-height',document.querySelector('.site-header').getBoundingClientRect().height+'px')).observe(document.querySelector('.site-header'));
const products=document.querySelector('.product-switcher').outerHTML;
document.querySelector('main').innerHTML='<section class="hero"><p class="eyebrow">SPLUNK SOAR</p><h1>Compare SOAR releases</h1>'+ (window.VersionCompassUpdates?.html('product:soar:introduction')||'') +'<div class="selector-card">'+products+'<div class="soar-controls">'+['deployment','from','to'].map(field).join('')+'</div><details class="soar-refine"><summary>Refine your environment</summary><div class="soar-controls">'+['installation','os','compliance','provider','region'].map(field).join('')+'</div></details><p id="soar-scope-note" class="soar-intro"></p></div><div class="report-actions"><button id="copy-link" type="button">Copy comparison link</button><button id="print-report" type="button">Print / PDF</button><span id="share-status" role="status"></span></div></section><div id="soar-warnings" role="alert"></div><div id="results" tabindex="-1"></div><article id="release-report" class="release-report" aria-label="Complete SOAR report"></article>';
document.querySelectorAll('input[name="product"]').forEach(el=>{el.checked=el.value==='soar';el.addEventListener('change',()=>{location.href=themed('?product='+el.value);});});
function citations(ids){return ids.map(id=>{const s=d.sources[id];return '<a href="'+esc(s.url)+'" target="_blank" rel="noopener noreferrer">'+esc(s.title)+'</a><span class="soar-source-scope"> · '+esc(s.section)+' · '+(s.outcome==='unavailable'?'Retrieval attempted ':'Verified section ')+esc(s.reviewed||s.checked)+'</span>';}).join('<br>');}
function record(r){return '<article class="soar-record" id="soar-'+esc(r.id)+'"><h3>'+esc(r.title)+'</h3><p class="soar-meta">'+esc(r.status)+(r.release?' · '+esc(r.release):'')+'</p>'+(r.outcome?'<p class="soar-outcome">'+esc(r.outcome)+'</p>':'')+'<p>'+esc(r.detail)+'</p>'+(r.qualification?'<p class="soar-qualification">'+esc(r.qualification)+'</p>':'')+'<details class="soar-evidence"><summary>Evidence and scope</summary><p>'+citations(r.src)+'</p><p>Claim verified: '+esc(r.verified||'Not established')+'. Applies only to the stated product, release and deployment.</p></details></article>';}
const list=a=>'<ul>'+a.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>';
function fullReport(m){
 const cloud=state.deployment==='cloud';
 const scope=['deployment',...(cloud?['compliance','provider','region']:['installation','os'])].map(k=>fields[k]+': '+(labels[state[k]]||state[k])).join(' · ');
 const restricted=cloud&&state.compliance==='fr-m'?record({id:'moderate-restrictions',title:'FedRAMP Moderate restrictions',status:'Required',detail:'Playbooks cannot use direct PostgreSQL access, cross-run filesystem sharing or direct vault filesystem access; use the automation APIs. Declared globals cannot be modified. Native data cannot be migrated from existing commercial or on-premises SOAR instances. Automation Brokers must run in FIPS mode.',src:['restricted'],verified:'2026-10-01'}):'';
 const req=m.targetRequirements;
 const rows=[['Automation runtime',req.runtime],...(!cloud?[['Supported OS',req.os],['Database',req.database],['Elasticsearch',req.search],['Bundled Universal Forwarder',req.forwarder],['Production sizing',req.sizing]]:[])];
 const requirementTable=(window.VersionCompassUpdates?.html('product:soar:requirements')||'')+'<table class="soar-requirements"><caption>Requirements at SOAR '+esc(state.to)+'</caption><thead><tr><th scope="col">Area</th><th scope="col">Target requirement</th></tr></thead><tbody>'+rows.map(([k,v])=>'<tr><th scope="row">'+esc(k)+'</th><td>'+esc(v)+'</td></tr>').join('')+'</tbody></table>';
 const ids=[...new Set([m.pathSource,...m.availability.src,...m.features.concat(m.requirements,m.technical,m.issues).flatMap(r=>r.src),...(cloud?['cloud']:req.src)])];
 const links=ids.map(id=>{const src=d.sources[id];return '<li><a href="'+esc(src.url)+'" target="_blank" rel="noopener noreferrer">'+esc(src.title)+'</a><p>'+esc(src.section)+'</p><p class="soar-meta">'+(src.outcome==='unavailable'?'Retrieval attempted '+esc(src.checked)+' · Rows unavailable': 'Section verified '+esc(src.reviewed||'Not established'))+'</p></li>';}).join('');
 const gates=[...m.requirements.filter(r=>r.release===state.to).map(r=>r.detail),...(!cloud?m.conditions.filter(x=>!x.startsWith('Complete Python')):[]),...m.issues.filter(r=>['build243','credential86'].includes(r.id)).map(r=>r.detail)];
 const path=m.path.length?'<ol class="soar-path" aria-label="'+(cloud?'Service milestones':'Upgrade steps')+'">'+m.path.map((v,i)=>'<li><span>'+esc(v)+'</span>'+(i<m.path.length-1?'<b aria-hidden="true">→</b>':'')+'</li>').join('')+'</ol>':'<p class="soar-alert">'+esc(m.routeStatus)+'</p>';
 const summary='<details class="soar-summary"><summary>This route at a glance · '+m.features.length+' feature '+(m.features.length===1?'change':'changes')+' · '+m.issues.length+' issue notices</summary><div class="soar-summary-grid"><div><h3>What you gain</h3>'+list(m.features.map(r=>r.outcome||r.title))+'</div><div><h3>What to resolve</h3>'+list(m.questions)+'</div></div></details>';
 return '<section class="section" id="route-takeaway"><p class="kicker">'+(cloud?'SOAR CLOUD · CAPABILITY COMPARISON':'CUSTOMER-MANAGED SOAR · UPGRADE ROUTE')+'</p><h2 id="path-title">'+esc(state.from)+' to '+esc(state.to)+'</h2>'+path+'<p class="soar-route-note"><strong>'+esc(m.routeStatus)+'.</strong> '+(cloud?'Confirm the release on your tenant. Splunk manages service updates.':'Validate the exact build, OS and deployment at each step.')+'</p><p class="soar-selection">'+esc(scope)+'</p><details class="soar-evidence"><summary>Official route and conditions</summary><p>'+citations([m.pathSource])+'</p>'+list(m.conditions)+'</details>'+(gates.length?'<aside class="soar-alert"><h3>'+ (cloud?'Before using these capabilities':'Before upgrading')+'</h3>'+list(gates)+'</aside>':'')+summary+'</section>'+
 (cloud?'<section class="section" id="environment-overview"><h2>Cloud availability</h2><p><strong>'+esc(m.availability.status)+'</strong> · '+esc(m.availability.detail)+'</p><p>'+citations(m.availability.src)+'</p>'+restricted+'</section>':'')+
 '<section class="section"><p class="kicker">WHAT CHANGES</p><h2 id="value-title">'+(cloud&&state.compliance!=='commercial'?'Feature changes to validate':'What you gain')+'</h2><div class="soar-grid">'+(m.features.map(record).join('')||'<p>No feature highlights are curated for this interval. Review the release notes below for full coverage.</p>')+'</div></section>'+
 '<section class="section"><h2 id="technical-title">Requirements and integrations</h2>'+requirementTable+'<details class="technical-panel" id="technical-panel"><summary><span class="technical-summary-icon" aria-hidden="true">&lt;/&gt;</span><span class="technical-summary-copy"><strong>Integration, sizing and upgrade detail</strong><span>'+m.requirements.length+(m.requirements.length===1?' requirement':' requirements')+' · '+m.technical.length+(m.technical.length===1?' technical change':' technical changes')+'</span></span><span class="technical-summary-action" aria-hidden="true"><span class="show-label">Show details</span><span class="hide-label">Hide details</span><span class="technical-chevron">⌄</span></span></summary><div class="soar-technical">'+m.requirements.concat(m.technical).map(record).join('')+'<p>Target requirements apply even when introduced before the current release. Compatibility rows do not replace current security and maintenance guidance.</p></div></details></section>'+
 '<section class="section"><h2 id="breaking-title">Known issues and security</h2>'+m.issues.map(record).join('')+'</section>'+
 '<section class="section"><h2 id="readiness-title">Resolve before scheduling</h2>'+list(m.questions)+'</section>'+
 '<section class="section"><h2 id="source-title">Official sources for this comparison</h2><ul class="soar-source-list">'+links+'</ul><details class="soar-evidence"><summary>Evidence coverage and remaining gaps</summary><p>'+esc(m.coverage)+'</p>'+(cloud?'<p>Cloud 8.7 GA is dated September 2 in release notes; its known-issues heading says September 3, and the service table retains an inconsistent April label. These are documentation discrepancies, not inferred rollout dates.</p>':'')+'<p><a href="'+esc(themed('?view=about'))+'">Browse the full source register</a></p><p>Independent planning aid. This report does not certify upgrade readiness or customer authorization.</p></details></section>';
}
function render(updateUrl=true){
 model=api.assess(state);const errors=[...new Set([...linkErrors,...model.errors])];
 document.querySelectorAll('[data-soar]').forEach(el=>{el.innerHTML=options(el.dataset.soar);el.value=state[el.dataset.soar];});
 for(const k of ['installation','os'])document.querySelector('[data-soar-field="'+k+'"]').hidden=state.deployment==='cloud';
 for(const k of ['compliance','provider','region'])document.querySelector('[data-soar-field="'+k+'"]').hidden=state.deployment!=='cloud';
 document.getElementById('soar-scope-note').textContent=state.deployment==='cloud'?'Compare service capabilities; confirm rollout on your tenant.':'Compare supported upgrade steps; refine installation and OS when needed.';
 document.getElementById('soar-warnings').innerHTML=errors.length?'<p>'+errors.map(esc).join('<br>')+'</p><button type="button" id="soar-reset">Use default SOAR comparison</button>':'';
 for(const id of ['copy-link','print-report'])document.getElementById(id).disabled=!!errors.length;
 document.getElementById('results').hidden=!!errors.length;document.getElementById('release-report').innerHTML='';
 if(errors.length){document.getElementById('soar-reset').onclick=()=>{state={...api.defaults};linkErrors=[];render();};return;}
 const open=document.getElementById('technical-panel')?.open,summary=document.querySelector('.soar-summary')?.open;
 document.getElementById('results').innerHTML=fullReport(model);document.getElementById('technical-panel').open=!!open;document.querySelector('.soar-summary').open=!!summary;
 document.title='Version Compass | SOAR '+state.from+' → '+state.to;
 if(updateUrl)history.replaceState(null,'',themed(api.url(state)));
}
document.querySelectorAll('[data-soar]').forEach(el=>el.addEventListener('change',()=>{const k=el.dataset.soar;state[k]=el.value;if(['deployment','to'].includes(k)&&!api.selectable('from',state).includes(state.from))state.from=api.selectable('from',state).at(-1);if(k==='provider'||k==='compliance'){state.region='unspecified';if(!api.selectable('provider',state).includes(state.provider))state.provider='unspecified';}linkErrors=[];render();}));
window.addEventListener('popstate',()=>{const p=api.read(location.search);state=p.state;linkErrors=p.errors;render(false);});
document.getElementById('copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);document.getElementById('share-status').textContent='Comparison link copied.';}catch{document.getElementById('share-status').textContent='Copy this link: '+location.href;}};
window.VersionCompassBuildSnapshot=()=>{if(linkErrors.length||model.errors.length)throw Error('Resolve selection warnings before exporting.');const html='<header class="report-title"><p>VERSION COMPASS · SOAR</p><h1>'+esc(state.from)+' to '+esc(state.to)+'</h1><p>'+esc(labels[state.deployment])+'</p></header>'+fullReport(model).replace(/\sid="[^"]*"/g,'');return window.VersionCompassReports.decorate(html.replace(/<details\b/g,'<details open'));};
function prepare(){if(linkErrors.length||model.errors.length)return;document.getElementById('release-report').innerHTML=window.VersionCompassBuildSnapshot();document.documentElement.classList.add('printing-report');}
window.addEventListener('beforeprint',prepare);window.addEventListener('afterprint',()=>document.documentElement.classList.remove('printing-report'));
document.getElementById('print-report').onclick=()=>{prepare();window.print();};
window.VersionCompassPage={getSelection:()=>({product:"soar",platform:state.deployment==="cloud"?"cloud":"enterprise",from:state.from,to:state.to,installation:state.installation,os:state.os,environment:{provider:state.provider,region:state.region,compliance:state.compliance}}),getLinkContext:()=>({needsConfirmation:!!(linkErrors.length||model.errors.length)})};
render();
}());
